use crate::i18n::Language;

pub(crate) fn sections(language: Language) -> &'static [(&'static str, &'static str)] {
    match language {
        Language::English => EN,
        Language::Russian => RU,
    }
}

const EN: &[(&str, &str)] = &[
    ("Supported keyboard and firmware", "This alpha supports the wired AK820 with the full permanent firmware v0.6.0-alpha.3 only. The application checks firmware compatibility when connecting. Unknown, custom, trial, or mismatched firmware is rejected."),
    ("Read and write settings", "Read the keyboard settings before editing. Each save is checked against the value read back from the keyboard. If a write or its verification fails, stop editing and explicitly choose Read settings again before continuing."),
    ("Layers and keys", "The editor supports 6 layers and 83 keys, plus one encoder with both directions and its regular matrix press. This firmware recognizes keycodes for Mod-Tap and Layer-Tap at 200 ms, simple TT layer toggle, modifier-only One-Shot Modifier, tri-layer activation of layer 3 when layers 1 and 2 are active, volatile Default Layer, Caps Word, Key Repeat, Alternate Key Repeat, NKRO and Space Cadet. Keycode availability describes firmware behavior; only controls exposed in the editor can be configured here. Persistent default-layer actions, Tap Dance, mouse actions, arbitrary overrides and general QMK settings are outside this alpha's scope."),
    ("Macros, combos and lighting", "There are 16 macros with a total capacity of 8192 bytes. Macro text is ASCII and supports Vial macro codes 1–7. To unlock macro editing, choose Unlock in the application, then hold Esc and Left Ctrl together for 3 seconds until the unlock completes. Unlock is an explicit user action. Up to 8 two-key combos are supported with a 40 ms term. This keyboard has 82 LEDs; the brightness limit is 160. RGB modes are Off (0), Direct (1), Solid (2), Breathing (6), Cycle all (13), Cycle left/right (14) and Reactive (31). Direct mode can be selected, but this alpha has no per-LED palette editor. The palette is kept in temporary device memory and cannot be read back."),
    ("Backups and firmware", "The existing .entlayout export is a partial editor snapshot, not a complete settings recovery or OEM firmware backup. Import for AK820 remains disabled until compatibility and pre-backup checks are implemented. Firmware flashing, OEM recovery and the operating-system LED helper are not part of this alpha. Keep firmware installation separate from settings editing."),
];

const RU: &[(&str, &str)] = &[
    ("Поддерживаемая клавиатура и прошивка", "Эта альфа-версия поддерживает проводную AK820 только с полной постоянной прошивкой v0.6.0-alpha.3. Приложение проверяет совместимость прошивки при подключении. Неизвестная, пользовательская, пробная или несовпадающая прошивка отклоняется."),
    ("Чтение и запись настроек", "Перед редактированием прочитайте настройки клавиатуры. После каждого сохранения приложение проверяет значение, прочитанное обратно с клавиатуры. Если запись или проверка завершилась ошибкой, прекратите редактирование и явно выберите «Прочитать настройки снова», прежде чем продолжать."),
    ("Слои и клавиши", "Редактор поддерживает 6 слоёв, 83 клавиши и один энкодер с обоими направлениями и обычным нажатием в матрице. Прошивка распознаёт коды Mod-Tap и Layer-Tap с интервалом 200 мс, простое переключение слоя TT, One-Shot Modifier только для модификаторов, автоматическое включение слоя 3 при активных слоях 1 и 2, временный Default Layer, Caps Word, Key Repeat, Alternate Key Repeat, NKRO и Space Cadet. Наличие кода в прошивке описывает её поведение; здесь можно настроить только действия, для которых есть элемент управления в редакторе. Постоянное назначение базового слоя, Tap Dance, действия мыши, произвольные переопределения и общие настройки QMK не входят в эту альфа-версию."),
    ("Макросы, Combo и подсветка", "Доступно 16 макросов общим объёмом до 8192 байт. Текст макросов — ASCII, поддерживаются коды макросов Vial 1–7. Чтобы разблокировать редактирование макросов, выберите Unlock в приложении, затем удерживайте Esc и левый Ctrl 3 секунды до завершения разблокировки. Это действие выполняется явно пользователем. Поддерживается до 8 двухклавишных Combo с интервалом 40 мс. В клавиатуре 82 светодиода; максимальная яркость — 160. Режимы RGB: Off (выключено, 0), Direct (прямое управление, 1), Solid (постоянный цвет, 2), Breathing (дыхание, 6), Cycle all (смена цветов, 13), Cycle left/right (смена цветов слева направо и справа налево, 14) и Reactive (реакция на нажатия, 31). Режим Direct можно выбрать, но в этой альфа-версии пока нет редактора палитры для отдельных светодиодов. Палитра хранится во временной памяти устройства и не считывается обратно."),
    ("Резервные копии и прошивка", "Существующий экспорт .entlayout — частичный снимок редактора, а не полная копия для восстановления настроек или штатной прошивки OEM. Импорт для AK820 пока отключён: ещё не реализованы проверки совместимости и обязательного предварительного бэкапа. Прошивка клавиатуры, восстановление OEM и системный помощник LED не входят в эту альфа-версию. Обновление прошивки выполняется отдельно от редактирования настроек."),
];
